package com.dreamseekers.progression;
import com.solegendary.reignofnether.resources.*;
import net.minecraft.nbt.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
final class WindProgressionCodecTest {
 private Resources account(){return new Resources("WindCodec",100,200,300);}
 private void earned(Resources r){var t=new CompoundTag();t.putInt("schema",1);t.putBoolean("wind",true);t.putInt("cost",0);t.putInt("train",0);t.putInt("research",0);r.addonData.put(DreamWindProgression.KEY,t);}
 @Test void originalZerosAndCeilPositiveComponentNeverFree(){assertEquals(0,DreamWindProgression.discount(0,45));assertEquals(1,DreamWindProgression.discount(1,45));assertEquals(35,DreamWindProgression.discount(50,30));assertEquals(28,DreamWindProgression.discount(50,45));assertEquals(53,DreamWindProgression.discount(75,30));assertEquals(42,DreamWindProgression.discount(75,45));assertEquals(99,DreamWindProgression.discount(180,45));assertThrows(IllegalArgumentException.class,()->DreamWindProgression.discount(-1,30));}
 @Test void contiguousTiersOnlyAndCapIsReal(){var r=account();earned(r);for(int family=0;family<3;family++){for(int n=1;n<=5;n++){assertTrue(DreamWindProgression.canAdvance(r,family,n));assertFalse(DreamWindProgression.canAdvance(r,family,n+1));DreamWindProgression.commitTier(r,family,n);assertEquals(n,DreamWindProgression.read(r).level(family));assertFalse(DreamWindProgression.canAdvance(r,family,n));}assertFalse(DreamWindProgression.canAdvance(r,family,6));}}
 @Test void sameAccountCopyAndCodecPreserveUnknownNamespaceAndResetClears(){var r=account();earned(r);DreamWindProgression.commitTier(r,0,1);var future=new CompoundTag();future.putInt("schema",99);future.putString("unknown","retain");r.addonData.put("futuremod:future",future);var t=new CompoundTag();r.writeExtended(t);var loaded=account();loaded.readExtended(t);assertEquals(r.accountEpoch,loaded.accountEpoch);assertEquals(r.addonData,loaded.addonData);var copy=account();copy.copyExtendedFrom(r);copy.addonData.getCompound("futuremod:future").putString("unknown","changed");assertEquals("retain",r.addonData.getCompound("futuremod:future").getString("unknown"));var old=loaded.accountEpoch;loaded.resetExtendedAccount();assertNotEquals(old,loaded.accountEpoch);assertTrue(loaded.addonData.isEmpty());}
 @Test void malformedProgressionFailsClosedWithoutErasingFundsOrUnknownPayload(){var r=account();earned(r);r.addonData.getCompound(DreamWindProgression.KEY).putInt("cost",5);assertFalse(DreamWindProgression.read(r).supported());var before=r.addonData.copy();assertFalse(DreamWindProgression.canAdvance(r,0,1));assertEquals(before,r.addonData);assertEquals(100,r.food);r.addonData.getCompound(DreamWindProgression.KEY).putInt("schema",99);assertFalse(DreamWindProgression.read(r).supported());assertEquals(99,r.addonData.getCompound(DreamWindProgression.KEY).getInt("schema"));}
 @Test void attachmentBoundsAndMalformedOuterFieldAreOpaqueNotLost(){var root=new CompoundTag();root.put("implicit_namespace",new CompoundTag());assertFalse(ResourceAddonData.valid(root));root=new CompoundTag();for(int i=0;i<17;i++)root.put("test:n"+i,new CompoundTag());assertFalse(ResourceAddonData.valid(root));root=new CompoundTag();var child=new CompoundTag();root.put("test:deep",child);for(int i=0;i<10;i++){var next=new CompoundTag();child.put("next",next);child=next;}assertFalse(ResourceAddonData.valid(root));root=new CompoundTag();child=new CompoundTag();child.putString("huge","x".repeat(65536));root.put("test:huge",child);assertFalse(ResourceAddonData.valid(root));var r=account();var parent=new CompoundTag();r.writeExtended(parent);parent.getCompound(ResourceAccountCodec.KEY).putString("addonData","future opaque");var loaded=account();loaded.readExtended(parent);assertTrue(loaded.extendedStateSupported());assertFalse(loaded.addonDataSupported());var roundtrip=new CompoundTag();loaded.writeExtended(roundtrip);assertEquals("future opaque",roundtrip.getCompound(ResourceAccountCodec.KEY).getString("addonData"));assertEquals(100,loaded.food);}
}
